#!/usr/bin/env bash
# GENERATED by scripts/build_user_scripts.py -- do not edit; re-run the master script instead.
# Bundle: inbox | Operation: write | Provider: from .env (DAYO_LLM_PROVIDER)
#
# Usage: inbox.sh [--text "..." | --clipboard] [extra note-writer options]
#   Input defaults to the clipboard when run from a terminal without --text/--clipboard.
#   Piped stdin is used as input when provided. Extra options override the baked-in ones.
set -euo pipefail

PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$PROJECT_ROOT"

if command -v uv >/dev/null 2>&1; then
  UV="$(command -v uv)"
else
  UV="$HOME/.local/bin/uv"
fi

args=("$@")
has_input=0
for arg in "$@"; do
  case "$arg" in
    --text|--text=*|--clipboard) has_input=1 ;;
  esac
done
if [ "$has_input" -eq 0 ] && [ -t 0 ]; then
  args+=(--clipboard)
fi

EXIT_CODE=0
"$UV" run note-writer write --bundle inbox "${args[@]}" || EXIT_CODE=$?

echo ""
if [ -t 0 ]; then
  read -rp "Press Enter to exit..." || true
elif [ -r /dev/tty ]; then
  read -rp "Press Enter to exit..." < /dev/tty || true
fi

exit "$EXIT_CODE"
